        <div className="comp-3d-grid"><label><span>Z position</span><input type="number" min="-8000" max="8000" step="10" value={layer.z ?? 0} onChange={(event) => props.onUpdateLayer({ z: Number(event.target.value) })} /></label><label><span>X rotation</span><input type="number" min="-360" max="360" value={layer.rotationX ?? 0} onChange={(event) => props.onUpdateLayer({ rotationX: Number(event.target.value) })} /></label><label><span>Y rotation</span><input type="number" min="-360" max="360" value={layer.rotationY ?? 0} onChange={(event) => props.onUpdateLayer({ rotationY: Number(event.target.value) })} /></label><label><span>X scale</span><input type="number" min="0" max="1000" value={layer.scaleX ?? 100} onChange={(event) => props.onUpdateLayer({ scaleX: Math.max(0, Number(event.target.value)) })} /></label><label><span>Y scale</span><input type="number" min="0" max="1000" value={layer.scaleY ?? 100} onChange={(event) => props.onUpdateLayer({ scaleY: Math.max(0, Number(event.target.value)) })} /></label><label><span>Z scale</span><input type="number" min="0" max="1000" value={layer.scaleZ ?? 100} onChange={(event) => props.onUpdateLayer({ scaleZ: Math.max(0, Number(event.target.value)) })} /></label></div>
