      {layer.mask?.enabled && <div className="mask-controls"><label className="field"><span>Mask shape</span><select className="director-select" value={layer.mask.shape} onChange={(event) => props.onUpdateLayer({ mask: { ...layer.mask!, shape: event.target.value as "rectangle" | "ellipse" } })}><option value="rectangle">Rectangle</option><option value="ellipse">Ellipse</option></select></label><label className="field"><span>Feather</span><div className="value-line"><input type="range" min="0" max="80" value={layer.mask.feather} onChange={(event) => props.onUpdateLayer({ mask: { ...layer.mask!, feather: Number(event.target.value) } })} /><strong>{layer.mask.feather}px</strong></div></label><label className="field"><span>Expansion</span><div className="value-line"><input type="range" min="-40" max="40" value={layer.mask.expansion} onChange={(event) => props.onUpdateLayer({ mask: { ...layer.mask!, expansion: Number(event.target.value) } })} /><strong>{layer.mask.expansion}%</strong></div></label><div className="mask-geometry-grid">{([['x', 'X', 0, 100], ['y', 'Y', 0, 100], ['width', 'Width', 1, 200], ['height', 'Height', 1, 200], ['rotation', 'Rotation', -180, 180]] as const).map(([key, label, min, max]) => <label className="field" key={key}><span>{label}</span><div className="value-line"><input type="range" min={min} max={max} step="1" value={layer.mask?.[key] ?? (key === 'width' || key === 'height' ? 100 : key === 'x' || key === 'y' ? 50 : 0)} onChange={(event) => props.onUpdateLayer({ mask: { ...layer.mask!, [key]: Number(event.target.value) } })} /><strong>{Math.round(layer.mask?.[key] ?? 0)}{key === 'rotation' ? '°' : '%'}</strong></div></label>)}</div><label><input type="checkbox" checked={layer.mask.inverted} onChange={(event) => props.onUpdateLayer({ mask: { ...layer.mask!, inverted: event.target.checked } })} /> Invert mask</label></div>}
